sections.body:
flowchart TD
  A[Quel besoin ?] --> B{API publique et cachable ?}
  B -- Oui --> REST[REST + JSON]
  B -- Non --> C{Client riche, besoins de donnees varies ?}
  C -- Oui --> GQL[GraphQL]
  C -- Non --> D{Communication interne performante ?}
  D -- Oui --> GRPC[gRPC + protobuf]
  D -- Non --> E{Integrer un systeme ancien ?}
  E -- Oui --> SOAP[SOAP / XML]
  E -- Non --> REST

query {
  roadmap(slug: "backend") {
    title
    nodes { slug title }   # on ne demande QUE ces champs
  }
}

service RoadmapService {
  rpc GetRoadmap (RoadmapRequest) returns (Roadmap);
}
message RoadmapRequest { string slug = 1; }
message Roadmap { string title = 1; repeated Node nodes = 2; }

// Émetteur : signature = HMAC_SHA256(secret, corps_brut)
//   en-tête -> X-Signature: sha256=<hex>
// Receveur :
//   1) recalcule HMAC_SHA256(secret, corps_brut_reçu)
//   2) compare en temps constant à la signature reçue
//   3) si différent -> 401 (rejeté) ; sinon traite l'événement
//   4) déduplique via event_id (livraison at-least-once)
